from pathlib import Path
P=Path(__file__).resolve().parent; R=P.parents[1]; N=P.parent/'bill-rest-helmet-north-coherent-v1'
t=(N/'build.py').read_text().replace('north','south').replace('rear helmet','front helmet').replace('rear-shell','front-shell')
