t=t.replace("'componentHashes':component_hashes,", "'componentHashes':component_hashes,'eyelids':{'donor':'character/bill-death-ground-helmet-south-lateral-v1/sources/canonical-closed-eyes.png','sha256':sha(closed),'generation':'exec-0b1ad8c7-6822-4afb-816d-f4980cb3c9fe','targets':[[13,10,17,12],[19,10,23,12]],'scope':'16 RGB pixels from authored eyelids; original pitched hardware and alpha unchanged'},")
